import SwiftUI

struct SiteSettingsView: View {
    let site: CappeSite; @Environment(\.dismiss) private var dismiss; @State private var name: String; @State private var subdomain: String; @State private var timezone = "UTC"; @State private var taxRate = ""; @State private var taxLabel = ""; @State private var shippingFlat = ""; @State private var freeShipping = ""; @State private var receiptPrefix = ""; @State private var error: String?
    init(site: CappeSite) { self.site = site; _name = State(initialValue: site.name); _subdomain = State(initialValue: site.subdomain ?? "") }
    var body: some View { Form { ErrorBanner(message: error); Section("Identity") { TextField("Site name", text: $name); TextField("Subdomain", text: $subdomain).textInputAutocapitalization(.never); TextField("Timezone", text: $timezone) }; Section("Checkout") { TextField("Tax rate (basis points)", text: $taxRate).keyboardType(.numberPad); TextField("Tax label", text: $taxLabel); TextField("Flat shipping (cents)", text: $shippingFlat).keyboardType(.numberPad); TextField("Free shipping threshold (cents)", text: $freeShipping).keyboardType(.numberPad); TextField("Receipt prefix", text: $receiptPrefix) }; Section("Publishing") { Text("Publishing and page editing stay on web.").font(.caption).foregroundStyle(.secondary); Link("Open web settings", destination: URL(string: "\(APIClient.shared.webOrigin)/cappe/sites/\(site.slug)/settings")!) } }.navigationTitle("Site settings").toolbar { ToolbarItem(placement: .confirmationAction) { Button("Save") { Task { await save() } }.disabled(name.isEmpty) } }.overlay(alignment: .top) { ErrorBanner(message: error) } }
    private func save() async { do { _ = try await SitesService.shared.update(siteId: site.id, CappeSiteUpdate(name: name, subdomain: subdomain.isEmpty ? nil : subdomain, timezone: timezone, tax_label: taxLabel.isEmpty ? nil : taxLabel, shipping_label: nil, receipt_prefix: receiptPrefix.isEmpty ? nil : receiptPrefix, status: nil, tax_rate_bps: Int(taxRate), shipping_flat_cents: Int(shippingFlat), shipping_free_threshold_cents: Int(freeShipping), is_multi_location: nil)); dismiss() } catch { self.error = error.localizedDescription } }
}
